export const LANGS = [["uk", "Українська"], ["ru", "Русский"], ["en", "English"]];
let cur = "uk";
export function setLang(l) { cur = D[l] ? l : "uk"; try { localStorage.setItem("lang", cur); } catch (e) {} }
export function getLang() { return cur; }
export function detectLang(tgLang) {
  let saved = null; try { saved = localStorage.getItem("lang"); } catch (e) {}
  const c = (saved || tgLang || navigator.language || "uk").slice(0, 2).toLowerCase();
  return D[c] ? c : "uk";
}
export function t(key, vars) {
  let s = (D[cur] && D[cur][key]) || D.uk[key] || key;
  if (vars) for (const k of Object.keys(vars)) s = s.split("{" + k + "}").join(String(vars[k]));
  return s;
}
export function dateFmt(d, withWeekday) {
  if (!d) return "";
  const loc = cur === "uk" ? "uk-UA" : cur === "ru" ? "ru-RU" : "en-GB";
  return new Date(d + "T00:00:00").toLocaleDateString(loc, withWeekday ? { weekday: "short", day: "numeric", month: "long" } : { day: "numeric", month: "short" });
}

